import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.DQbZ8cc1.js";const b=JSON.parse('{"title":"BBS-GO Installation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide.md","filePath":"docs/guide.md"}'),s={name:"docs/guide.md"};function n(o,a,d,r,c,h){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="bbs-go-installation-guide" tabindex="-1">BBS-GO Installation Guide <a class="header-anchor" href="#bbs-go-installation-guide" aria-label="Permalink to “BBS-GO Installation Guide”">​</a></h1><h2 id="_1-requirements" tabindex="-1">1. Requirements <a class="header-anchor" href="#_1-requirements" aria-label="Permalink to “1. Requirements”">​</a></h2><ul><li>OS: Windows / macOS / Linux</li><li>Memory: 2GB+ recommended</li><li>Database: <ul><li>MySQL 8+ recommended for production</li><li>SQLite available for local trial</li></ul></li></ul><h2 id="_2-download-release-package" tabindex="-1">2. Download Release Package <a class="header-anchor" href="#_2-download-release-package" aria-label="Permalink to “2. Download Release Package”">​</a></h2><p>Releases: <a href="https://github.com/mlogclub/bbs-go/releases/latest" target="_blank" rel="noreferrer">https://github.com/mlogclub/bbs-go/releases/latest</a></p><table tabindex="0"><thead><tr><th>Platform</th><th>File</th></tr></thead><tbody><tr><td>Windows</td><td><code>bbs-go-windows-x86_64.zip</code></td></tr><tr><td>macOS Intel</td><td><code>bbs-go-macos-amd64.zip</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>bbs-go-macos-arm64.zip</code></td></tr><tr><td>Linux 64-bit</td><td><code>bbs-go-linux-amd64.zip</code></td></tr><tr><td>Linux 32-bit</td><td><code>bbs-go-linux-386.zip</code></td></tr></tbody></table><h2 id="_3-start-the-program" tabindex="-1">3. Start the Program <a class="header-anchor" href="#_3-start-the-program" aria-label="Permalink to “3. Start the Program”">​</a></h2><p>Extract package, enter directory, then run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux/macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bbs-go</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbs-go.exe</span></span></code></pre></div><p>Default port: <code>8082</code>.</p><h2 id="_4-first-time-installation" tabindex="-1">4. First-Time Installation <a class="header-anchor" href="#_4-first-time-installation" aria-label="Permalink to “4. First-Time Installation”">​</a></h2><p>Open in browser:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:8082/install</span></span></code></pre></div><p>Installer steps:</p><ol><li>Select language (<code>en-US</code> / <code>zh-CN</code>)</li><li>Select database (MySQL or SQLite)</li><li>Fill site information</li><li>Create admin account</li><li>Finish installation</li></ol><p>The system will initialize config and data automatically.</p><h2 id="_5-access-urls" tabindex="-1">5. Access URLs <a class="header-anchor" href="#_5-access-urls" aria-label="Permalink to “5. Access URLs”">​</a></h2><ul><li>Site: <code>http://localhost:8082/</code></li><li>Admin: <code>http://localhost:8082/admin</code></li></ul><h2 id="_6-troubleshooting" tabindex="-1">6. Troubleshooting <a class="header-anchor" href="#_6-troubleshooting" aria-label="Permalink to “6. Troubleshooting”">​</a></h2><h3 id="port-already-in-use" tabindex="-1">Port already in use <a class="header-anchor" href="#port-already-in-use" aria-label="Permalink to “Port already in use”">​</a></h3><p>Change <code>Port</code> in <code>bbs-go.yaml</code> or stop the conflicting process.</p><h3 id="database-connection-failed" tabindex="-1">Database connection failed <a class="header-anchor" href="#database-connection-failed" aria-label="Permalink to “Database connection failed”">​</a></h3><ul><li>MySQL: verify host, port, username, password, and database name</li><li>SQLite: choose SQLite directly in installer (no manual DB setup needed)</li></ul><h3 id="production-recommendations" tabindex="-1">Production recommendations <a class="header-anchor" href="#production-recommendations" aria-label="Permalink to “Production recommendations”">​</a></h3><ul><li>Use MySQL</li><li>Put Nginx/Caddy in front and enable HTTPS</li><li>Backup database and uploads regularly</li></ul><h2 id="_7-advanced-docs" tabindex="-1">7. Advanced Docs <a class="header-anchor" href="#_7-advanced-docs" aria-label="Permalink to “7. Advanced Docs”">​</a></h2><ul><li><a href="./installation/index.html">Installation &amp; Deployment Overview</a></li><li><a href="./installation/server/install.html">Service Deployment</a></li><li><a href="./installation/docker.html">Docker Deployment</a></li></ul>`,27)])])}const m=e(s,[["render",n]]);export{b as __pageData,m as default};
